SELECT "nct", "author", "year", "pubmed_id", "trial_phase", "treatment_regimen", "name_of_ici", "class_of_ici", "type_of_combination", "control_regimen", "cancer_type" FROM public."clinical_trials" WHERE "cancer_type" ILIKE '%colorectal%' AND "trial_phase" = '3' AND "class_of_ici" = 'PD1' AND "number_of_arms" = 1 AND "type_of_combination" = 'monotherapy' AND "type_of_control" = 'standard' ORDER BY "year" DESC;